  ('61000000-0000-0000-0000-000004010213', '51000000-0000-0000-0000-000000040102', 'very_hard', 1, '4 × ___ = 6 × 6', 'fill_blank', NULL, '"9"'::jsonb, '6 × 6 = 36, so 4 × ? = 36. 4 × 9 = 36.', NULL, NULL, '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000004010214', '51000000-0000-0000-0000-000000040102', 'very_hard', 1, '___ × 5 = 80 ÷ 2', 'fill_blank', NULL, '"8"'::jsonb, '80 ÷ 2 = 40, so ? × 5 = 40. 8 × 5 = 40.', NULL, NULL, '90000000-0000-0000-0000-000000000001'),
