  ('61000000-0000-0000-0000-000005030124', '51000000-0000-0000-0000-000000050301', 'medium', 1, 'What number is shown by the dot on the number line?', 'short_answer', NULL, '"2.14"'::jsonb, 'From 2.1 to 2.2 is 10 hundredths, so each jump is 0.01. The dot is 4 jumps past 2.1: 2.14.', '{"kind":"number_line","from":2.1,"to":2.2,"jumps":10,"dotAt":4}'::jsonb, NULL, '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000005030125', '51000000-0000-0000-0000-000000050301', 'hard', 1, 'Put these decimals in order from smallest to largest.', 'ordering', '[{"id":"a","text":"1.009"},{"id":"b","text":"1.09"},{"id":"c","text":"1.1"},{"id":"d","text":"1.109"},{"id":"e","text":"1.19"}]'::jsonb, '["a","b","c","d","e"]'::jsonb, 'Write them with three places: 1.009, 1.090, 1.100, 1.109, 1.190. Now compare them like whole numbers.', NULL, NULL, '90000000-0000-0000-0000-000000000001'),
