  ('61000000-0000-0000-0000-000005030311', '51000000-0000-0000-0000-000000050303', 'easy', 1, '0.25 is greater than 0.3.', 'true_false', NULL, '"false"'::jsonb, '0.3 is the same as 0.30. 25 hundredths is less than 30 hundredths, so 0.25 is smaller.', NULL, NULL, '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000005030312', '51000000-0000-0000-0000-000000050303', 'medium', 1, 'What number does the dot on the number line show?', 'short_answer', NULL, '"1.4"'::jsonb, 'From 1 to 2 there are 10 jumps, so each jump is 0.1. The dot is 4 jumps past 1, so it is at 1.4.', '{"kind":"number_line","from":1,"to":2,"jumps":10,"dotAt":4}'::jsonb, NULL, '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000005030313', '51000000-0000-0000-0000-000000050303', 'medium', 1, 'Which of these are less than 0.6? Choose all that are right.', 'multi_select', '[{"id":"a","text":"0.59"},{"id":"b","text":"0.61"},{"id":"c","text":"0.509"},{"id":"d","text":"0.6"},{"id":"e","text":"0.06"}]'::jsonb, '["a","c","e"]'::jsonb, 'Write them with three places: 0.590, 0.610, 0.509, 0.600 and 0.060. The ones under 0.600 are 0.59, 0.509 and 0.06.', NULL, NULL, '90000000-0000-0000-0000-000000000001'),
